macro_rules! deps {
    () => {
        Flags!();
        Error!();
        GenThenTime!();
    };
}

macro_rules! remove_redundant {
    () => {
        deps!();
        # [doc = " Remove all those commits from `commits` if they are in the history of another commit in `commits`."] # [doc = " That way, we return only the topologically most recent commits in `commits`."] fn remove_redundant (commits : & [(ObjectId , GenThenTime)] , graph : & mut Graph < '_ , '_ , graph :: Commit < Flags > > ,) -> Result < Vec < ObjectId > , Error > { if commits . is_empty () { return Ok (Vec :: new ()) ; } graph . clear_commit_data (| f | * f = Flags :: empty ()) ; let _span = gix_trace :: detail ! ("gix_revision::remove_redundant()" , num_commits = % commits . len ()) ; let sorted_commits = { let mut v = commits . to_vec () ; v . sort_by (| a , b | a . 1 . cmp (& b . 1)) ; v } ; let mut min_gen_pos = 0 ; let mut min_gen = sorted_commits [min_gen_pos] . 1 . generation ; let mut walk_start = Vec :: with_capacity (commits . len ()) ; for (id , _) in commits { let commit = graph . get_mut (id) . expect ("previously added") ; commit . data |= Flags :: RESULT ; for parent_id in commit . parents . clone () { graph . get_or_insert_full_commit (parent_id , | parent | { if ! parent . data . contains (Flags :: STALE) { parent . data |= Flags :: STALE ; walk_start . push ((parent_id , GenThenTime :: from (& * parent))) ; } }) ? ; } } walk_start . sort_by (| a , b | a . 0 . cmp (& b . 0)) ; walk_start . iter_mut () . for_each (| (id , _) | graph . get_mut (id) . expect ("added previously") . data . remove (Flags :: STALE)) ; let mut count_still_independent = commits . len () ; let mut stack = Vec :: new () ; while let Some ((commit_id , commit_info)) = walk_start . pop () . filter (| _ | count_still_independent > 1) { stack . clear () ; graph . get_mut (& commit_id) . expect ("added") . data |= Flags :: STALE ; stack . push ((commit_id , commit_info)) ; while let Some ((commit_id , commit_info)) = stack . last () . copied () { let commit = graph . get_mut (& commit_id) . expect ("all commits have been added") ; let commit_parents = commit . parents . clone () ; if commit . data . contains (Flags :: RESULT) { commit . data . remove (Flags :: RESULT) ; count_still_independent -= 1 ; if count_still_independent <= 1 { break ; } if * commit_id == * sorted_commits [min_gen_pos] . 0 { while min_gen_pos < commits . len () - 1 && graph . get (& sorted_commits [min_gen_pos] . 0) . expect ("already added") . data . contains (Flags :: STALE) { min_gen_pos += 1 ; } min_gen = sorted_commits [min_gen_pos] . 1 . generation ; } } if commit_info . generation < min_gen { stack . pop () ; continue ; } let previous_len = stack . len () ; for parent_id in & commit_parents { if graph . get_or_insert_full_commit (* parent_id , | parent | { if ! parent . data . contains (Flags :: STALE) { parent . data |= Flags :: STALE ; stack . push ((* parent_id , GenThenTime :: from (& * parent))) ; } }) ? . is_some () { break ; } } if previous_len == stack . len () { stack . pop () ; } } } Ok (commits . iter () . filter_map (| (id , _info) | { graph . get (id) . filter (| commit | ! commit . data . contains (Flags :: STALE)) . map (| _ | * id) }) . collect ()) }
    };
}

remove_redundant!()